from research_helpers import *
a=ev('https://www.biovaxys.com/newsroom/2025-corporate-review','Portfolio and planned licensing reviewed. Body explicitly defines DPX-rPA as anthrax; contradictory peanut-allergy shorthand in boilerplate not reused as an alias.')
b=ev('https://www.prnewswire.com/news-releases/biovaxys-completes-the-acquisition-of-all-intellectual-property-immunotherapeutics-platform-technology-and-clinical-stage-assets-of-the-former-imv-inc-302067847.html','Completed IMV asset acquisition supports acquired technology associations; not attributed as original BioVaxys invention.')
c=ev('https://www.biovaxys.com/dpx','Current DPX delivery platform identity.')
d=ev('https://webfiles.thecse.com/20260406_BIOV_CSE_Form_7_March_2026_To_File.pdf?Bf03AkhSnvDsgMUi4BboSIXaNsXjNL7M=','March 2026 issuer filing identifies signed Adverna research agreement for three veterinary mRNA vaccine programmes; disease acronym inconsistency not propagated.')
e=ev('https://www.biovaxys.com/newsroom/biovaxys-announces-bvx-0320-poster-presentation-at-isirv-who-virtual-conference','Historical COVID vaccine and T-cell diagnostic identities; no trial start or approval inferred.')
products=[p('Maveropepimut-S','Survivin-directed cancer immunotherapy; clinical data and out-licensing efforts reported.',a,life='development',roles=['commercial_partner'],aliases=['MVP-S'],evidence=[a,b]),p('DPX immune-educating platform','Antigen-delivery technology acquired from IMV.',c,life='development',roles=['commercial_partner'],typ='technology',sub='research_tools',evidence=[c,b]),p('HapTenix','Haptenized tumour-cell immunotherapy technology.',a,life='development',typ='technology',sub='research_tools'),p('BVX-0918','Personalized ovarian-cancer vaccine candidate.',a,life='development'),p('DPX+SurMAGE','Survivin/MAGE-A9 dual-target immunotherapy candidate.',a,life='development'),p('DPX-RSV','Investigational RSV vaccine; Phase 1 completed, subsequent development partner sought.',a,life='development',roles=['commercial_partner']),p('BioVaxys DPX influenza vaccine programme','Historical influenza vaccine programme encompassing described antigen formats; exact formulations unresolved.',a,roles=['commercial_partner']),p('DPX-rPA anthrax vaccine','Investigational recombinant protective-antigen anthrax vaccine programme; current clinical stage unresolved.',a,roles=['commercial_partner']),p('BioVaxys DPX peanut-allergy vaccine programme','Investigational allergy-desensitization programme. Conflicting DPX+rPA shorthand withheld.',a),p('SpayVac','Investigational animal immunocontraception vaccine using licensed delivery technology; regulatory submission efforts described, approval not inferred.',a,life='development',roles=['commercial_partner'])]
for disease in ['rabies','leptospirosis','feline infectious peritonitis']:products.append(p('BioVaxys Adverna DPX-mRNA '+disease+' vaccine programme','Early veterinary vaccine research programme; no named clinical molecule or approval inferred.',d,life='development',roles=['developer']))
products += [p('BVX-0320','Historical hapten-modified SARS-CoV-2 vaccine candidate; current development status unresolved.',e),p('CoviDTH','Historical investigational SARS-CoV-2 T-cell response diagnostic; current status unresolved.',e,sub='diagnostics')]
co=dict(company_id='cmp_30fc0ac4-099c-4406-976f-a0a9b9a8a349',products=products,evidence=[a,b,c,d,e],status='partial',coverage_note='15 named candidates/programmes/platforms including veterinary collaborations and two historical COVID offerings. IMV asset acquisition verified; no current commercial vaccine sales or approval inferred. DPX-rPA body-defined anthrax separated from peanut programme because issuer boilerplate conflicts. MVP-S combination regimens not duplicate molecules; platforms overlap formulations. Partial: DPX Ebola/legacy IMV vaccine candidates, BVX variants, trial current status and newer licensing agreements require further review. Veterinary peritonitis acronym inconsistency omitted.')
assert len(products)==15
(out/'batch-0394.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
